    imageUrl: "/images/tipps/verdauung/6.jpg",
    imageAlt: "Gekochtes Hühnchen und Reis in einer Schüssel – Schonkost für Hunde",
    content: `Dein Hund hat Durchfall und du fragst dich, was du tun kannst. Die gute Nachricht: Akuter Durchfall ohne andere Begleitsymptome ist bei Hunden häufig und lässt sich oft mit einer kurzen Schonkostphase gut überbrücken. Die klassische Kombination aus gekochtem Hühnchen und weich gekochtem Reis hat sich dabei bewährt.

## Warum Schonkost dem Darm hilft

Bei Durchfall ist die Darmschleimhaut gereizt und die normale Verdauungsleistung eingeschränkt. Fettreiches, komplexes oder gewürztes Futter würde den Darm weiter belasten. Schonkost ist leicht verdaulich, arm an Fett und Ballaststoffen und belastet die Darmwand kaum. Der Darm bekommt so die Möglichkeit, sich zu erholen, ohne auf Nahrung völlig verzichten zu müssen.

## Die klassische Schonkost: Hühnchen und Reis

Gekochte, magere Hühnchenbrust ohne Haut, Knochen und Würze ist die am häufigsten empfohlene Eiweißquelle für die Schonkostphase. Sie ist leicht verdaulich und wird von den meisten Hunden problemlos akzeptiert. Weich gekochter, weißer Reis dient als bindende Kohlenhydratquelle, die den Kot festigen kann. Das Verhältnis liegt üblicherweise bei etwa einem Teil Hühnchen zu zwei Teilen Reis.

## Wie lange Schonkost?

Ein bis zwei Tage Schonkost reichen für die meisten unkomplizierten Durchfallfälle. Danach leitest du schrittweise zurück zum normalen Futter über: am dritten Tag etwa die Hälfte Schonkost, die Hälfte Normalfutter, dann weiter steigern. Ein abrupter Rückwechsel kann den nächsten Schub auslösen.

## Was du sonst noch beachten solltest

Sorge während der Durchfallphase für ausreichend Wasser. Hunde verlieren bei Durchfall mehr Flüssigkeit als üblich, und eine leichte Austrocknung kann schnell eintreten. Beobachte deinen Hund aufmerksam auf weitere Symptome wie Erbrechen, Blut im Kot, Fieber oder Apathie.

## Wann Schonkost nicht mehr reicht

Schonkost ist eine Erstmaßnahme bei leichtem, unkompliziertem Durchfall ohne Begleitsymptome. Sie ersetzt keine tierärztliche Behandlung. Wenn der Durchfall nach 48 Stunden nicht besser wird, Blut auftritt, dein Hund erbricht, Fieber hat oder sehr apathisch wirkt, ist ein sofortiger Tierarztbesuch erforderlich.

## Häufige Fragen

### Kann ich statt Hühnchen auch etwas anderes nehmen?
Ja, magerer Truthahn oder mageres Rind funktionieren ähnlich. Wichtig ist, dass das Fleisch gekocht und fettarm ist und keinerlei Würze enthält.

### Darf ich meinen Hund bei Durchfall fasten lassen?
Eine kurze Fastenphase war früher üblich, wird heute aber nicht mehr generell empfohlen, besonders nicht bei Welpen, kleinen Rassen oder bei Schwäche. Besser ist leichte, gut verträgliche Schonkost.

### Kann ich auch Fertig-Schonkostfutter aus dem Handel nutzen?
Ja, es gibt spezielle Diätfutter für die Magenregeneration. Diese sind praktisch und ebenfalls geeignet. Dein Tierarzt kann dir eine Empfehlung geben.

## Das Wichtigste in Kürze

- Schonkost entlastet den gereizten Darm und unterstützt die Erholung.
- Bewährte Kombination: gekochte Hühnchenbrust und weich gekochter weißer Reis.
- Schonkostphase: 1–2 Tage, dann schrittweise zurück zum normalen Futter.
- Auf ausreichend Flüssigkeitsversorgung achten.
- Bei Blut, Erbrechen, Fieber oder Dauer über 48 Stunden sofort zum Tierarzt.`,
