    keywords: ["Hund Verdauung ganzheitlich", "Stress Hund Magen-Darm", "Bewegung Hund Verdauung"],
    geoRelevant: false,
    internalLinks: ["/tipps/verdauung", "/tipps/hydration", "/tipps/ernaehrung"],
    relatedTips: [91, 97, 100],
    readingTime: 5,
    lastUpdated: "2026-06-15T10:00:00Z",
